// Writes src/generated/schema.d.ts: the types openapi-typescript makes of the repo's openapi/public.json. The staleness test
// (src/generated.test.ts) calls generate() and compares it with the committed file, so `just check` fails on a drift.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const BANNER = `/**
 * This file was auto-generated by openapi-typescript from openapi/public.json
 * (npm run generate -w packages/client, or just openapi-refresh). Do not make direct changes to the file.
 */

`;

export const specUrl = new URL('../../../openapi/public.json', import.meta.url);
export const schemaUrl = new URL('../src/generated/schema.d.ts', import.meta.url);

/** @returns {Promise<string>} the contents schema.d.ts should have */
export const generate = async () => `${BANNER}${astToString(await openapiTS(specUrl))}`;

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  mkdirSync(dirname(fileURLToPath(schemaUrl)), { recursive: true });
  writeFileSync(schemaUrl, await generate());
}
